import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) == 0:
        high_ts = pd.NaT
    else:
        high_ts = watermark["high_ts"].iloc[0]

    # Filter events strictly after watermark
    if pd.isna(high_ts):
        events = cdc_events.copy()
    else:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort globally by (event_ts, event_seq) to apply sequentially
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    seven_days = timedelta(days=7)

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        ev_email = ev["email"]

        if op == "U":
            if uid not in state or state[uid]["status"] == "ACTIVE":
                state[uid] = {
                    "email": ev_email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            elif state[uid]["status"] == "DELETED":
                delta = ts - state[uid]["status_ts"]
                if delta > seven_days:
                    state[uid] = {
                        "email": ev_email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else: discard (sticky deletion window)
            else:
                # unexpected status, treat as upsert
                state[uid] = {
                    "email": ev_email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
        elif op == "D":
            if uid in state:
                preserved_email = state[uid]["email"]
            else:
                preserved_email = ev_email
            state[uid] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": ts,
            }

    if state:
        out_rows = []
        for uid, info in state.items():
            out_rows.append({
                "user_id": uid,
                "email": info["email"],
                "status": info["status"],
                "status_ts": info["status_ts"],
            })
        new_snapshot = pd.DataFrame(out_rows, columns=["user_id", "email", "status", "status_ts"])
    else:
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])

    new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
    new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])

    return {"new_snapshot": new_snapshot}
